  --secondary: hsl(124.6 40.11% 93.94%);
  --secondary-foreground: hsl(124.98 58.54% 23.69%);
  --muted: hsl(33.73 26.25% 91.6%);
  --muted-foreground: hsl(15 25.98% 34.17%);
  --accent: hsl(121.99 38.82% 84.94%);
  --accent-foreground: hsl(124.98 58.54% 23.69%);
